const d = $input.item.json;
const cash = d.cash || 0;
const portfolio = d.portfolio || [];
const bubbleScore = d.bubbleScore || 0;
const riskPhase = d.riskPhase || 'Normal 🟢';
const positionMultiplier = d.positionMultiplier || 1;

// Dynamically build owned tickers list
const ownedTickers = portfolio.map(p => p.ticker).join(', ');

// Count how many ETFs vs growth stocks already in portfolio
const etfTickers = ['VUAGl_EQ','ISFl_EQ','SWLDl_EQ','VFEMl_EQ','VERXl_EQ','EQQQl_EQ'];
const growthTickers = ['PLTR_US_EQ','AMD_US_EQ','SOFI_US_EQ','IONQ_US_EQ','RKLB_US_EQ','HOOD_US_EQ','COIN_US_EQ','AFRM_US_EQ','TSLA_US_EQ','NVDA_US_EQ'];
const ownedList = portfolio.map(p => p.ticker);
const etfsOwned = ownedList.filter(t => etfTickers.includes(t)).length;
const growthOwned = ownedList.filter(t => growthTickers.includes(t)).length;

// Bias instruction: push toward under-represented category
let balanceInstruction;
if (etfsOwned > growthOwned + 1) {
  balanceInstruction = 'IMPORTANT: Portfolio is ETF-heavy. You MUST include at least 2 growth stocks in your trades today. Lean toward PLTR_US_EQ, AMD_US_EQ, SOFI_US_EQ, IONQ_US_EQ, RKLB_US_EQ, HOOD_US_EQ, COIN_US_EQ, AFRM_US_EQ.';
} else if (growthOwned > etfsOwned + 1) {
  balanceInstruction = 'IMPORTANT: Portfolio is growth-heavy. You MUST include at least 1 ETF for stability. Lean toward ISFl_EQ, SWLDl_EQ, VFEMl_EQ, EQQQl_EQ.';
} else {
  balanceInstruction = 'AIM for a MIX: include at least 1 ETF and at least 1 growth stock in your trades. Do not pick all ETFs or all growth stocks.';
}

const bubbleWarning = bubbleScore >= 13 ? 'CRITICAL: Do NOT trade today'
  : bubbleScore > 4 ? 'ELEVATED RISK: Reduce position sizes by ' + Math.round((1 - positionMultiplier) * 100) + '%'
  : 'Normal market conditions';

const systemPrompt = `You are a JSON-only trading bot for a UK ISA targeting 15% annual growth. Output ONLY a JSON object starting with { and ending with }. No prose, no explanation.

VERIFIED T212 TICKERS (use ONLY these):
Growth stocks: PLTR_US_EQ, AMD_US_EQ, SOFI_US_EQ, IONQ_US_EQ, RKLB_US_EQ, HOOD_US_EQ, COIN_US_EQ, AFRM_US_EQ, TSLA_US_EQ, NVDA_US_EQ
ETFs (stability/diversification): ISFl_EQ, SWLDl_EQ, VFEMl_EQ, VERXl_EQ, EQQQl_EQ, VUAGl_EQ

NEVER use: VUSAl_EQ, SCHD, IAU, GLD, QQQ, IVV

ALREADY IN PORTFOLIO - DO NOT BUY MORE OF THESE: ${ownedTickers}

${balanceInstruction}

RULES:
1. Total trades MUST NOT exceed £${cash}
2. Use "amount" field not "quantity"
3. Max 40% of cash per trade
4. Minimum £5 per trade
5. Pick 2-3 different instruments
6. NEVER repeat a ticker already in portfolio
7. MUST pick at least 1 growth stock (PLTR_US_EQ, AMD_US_EQ, SOFI_US_EQ, IONQ_US_EQ, RKLB_US_EQ, HOOD_US_EQ, COIN_US_EQ, AFRM_US_EQ) unless ALL are already owned
8. Allocate based on research signals — favour momentum, dip opportunities and sentiment

FORMAT (example uses growth stock intentionally): {"trades":[{"ticker":"PLTR_US_EQ","amount":50.00,"reason":"reason here","isDip":false}],"summary":"brief summary"}`;

const userPrompt = `ETF RESEARCH: ${d.etfContext || 'none'}
GROWTH STOCKS: ${d.growthContext || 'none'}
MARKET OUTLOOK: ${d.marketContext || 'none'}
DIP OPPORTUNITIES: ${d.dipContext || 'none'}
PORTFOLIO: ${JSON.stringify(portfolio)}
CASH: £${cash}
RISK: ${riskPhase} bubble score ${bubbleScore}/15 - ${bubbleWarning}
ECONOMIC: ${d.econContext || 'No major events'}
PORTFOLIO BALANCE: ${etfsOwned} ETFs vs ${growthOwned} growth stocks owned.

Output JSON only. Total trades must not exceed £${cash}. Do NOT buy: ${ownedTickers}`;

return [{json: {cash, portfolio, systemPrompt, userPrompt}}];

// Parse Trades - robust extractor for LLM JSON responses (Run Once for Each Item)
const raw = String($input.item.json.message?.content || $input.item.json.content || "");
const cash = Number($("Build Ollama Prompt").item.json.cash) || 0;

function safeOut(extra) {
  const base = { trades: [], summary: "", cash: cash, tradeCount: 0, hasDipTrades: false, parseError: null, rawPreview: raw.substring(0, 300) };
  return { json: Object.assign(base, extra || {}) };
}

if (!raw || !raw.trim()) { return safeOut({ parseError: "Empty LLM response" }); }

// 1. Strip markdown code fences only
let cleaned = raw
  .replace(/```(?:json|JSON)?\s*/g, "")
  .replace(/```/g, "")
  .trim();

// 2. String-aware sanitisation: strip JS comments, fix bad escape chars, drop trailing commas
function sanitizeJsonish(s) {
  let out = "";
  let inStr = false, strCh = "", esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const next = s[i + 1];
    if (esc) {
      // We just consumed the backslash. Check if this is a valid JSON escape.
      const validEsc = ["\"", "\\", "/", "b", "f", "n", "r", "t", "u"];
      if (validEsc.indexOf(ch) === -1) {
        // Drop the backslash, keep the character literally.
        // Remove the backslash that we already added to out.
        if (out.length > 0 && out[out.length - 1] === "\\") {
          out = out.slice(0, -1);
        }
        out += ch;
      } else {
        out += ch;
      }
      esc = false;
      continue;
    }
    if (inStr) {
      if (ch === "\\") { out += ch; esc = true; continue; }
      if (ch === strCh) { inStr = false; }
      // Newlines/tabs inside strings break JSON.parse - escape them.
      if (ch === "\n") { out += "\\n"; continue; }
      if (ch === "\r") { out += "\\r"; continue; }
      if (ch === "\t") { out += "\\t"; continue; }
      out += ch;
      continue;
    }
    if (ch === "\"" || ch === "'") { inStr = true; strCh = ch; out += ch; continue; }
    // Line comment outside string
    if (ch === "/" && next === "/") {
      while (i < s.length && s[i] !== "\n") i++;
      continue;
    }
    // Block comment outside string
    if (ch === "/" && next === "*") {
      i += 2;
      while (i < s.length - 1 && !(s[i] === "*" && s[i + 1] === "/")) i++;
      i++;
      continue;
    }
    out += ch;
  }
  // Convert single-quoted strings to double-quoted (best-effort)
  // Skipped: risky to do generally. Trailing comma cleanup:
  out = out.replace(/,\s*([}\]])/g, "$1");
  return out;
}
cleaned = sanitizeJsonish(cleaned);

// 3. Extract first balanced { } or [ ] block (string-aware)
function extractBalanced(str, open, close) {
  const startIdx = str.indexOf(open);
  if (startIdx === -1) return null;
  let depth = 0, inStr = false, strCh = "", esc = false;
  for (let i = startIdx; i < str.length; i++) {
    const ch = str[i];
    if (esc) { esc = false; continue; }
    if (ch === "\\") { esc = true; continue; }
    if (inStr) { if (ch === strCh) inStr = false; continue; }
    if (ch === "\"" || ch === "'") { inStr = true; strCh = ch; continue; }
    if (ch === open) depth++;
    else if (ch === close) { depth--; if (depth === 0) return str.substring(startIdx, i + 1); }
  }
  return null;
}

let parsed = null;
let parseError = null;
const candidates = [];
const objBlock = extractBalanced(cleaned, "{", "}");
const arrBlock = extractBalanced(cleaned, "[", "]");
if (objBlock) candidates.push(objBlock);
if (arrBlock) candidates.push(arrBlock);
candidates.push(cleaned);

for (const c of candidates) {
  try { parsed = JSON.parse(c); parseError = null; break; }
  catch (e) { parseError = e.message; }
}

if (parsed === null || parsed === undefined) {
  return safeOut({ parseError: "JSON parse failed: " + parseError });
}

// 4. Normalise wrappers: {trades:[]}, {portfolio:[...]}, {json:{...}}, [{json:{...}}], [trade,trade]
function unwrap(p) {
  if (Array.isArray(p)) {
    if (p.length === 0) return {};
    if (p[0] && typeof p[0] === "object" && p[0].json && typeof p[0].json === "object") return p[0].json;
    if (p[0] && typeof p[0] === "object" && (p[0].ticker || p[0].symbol)) return { trades: p };
    return (p[0] && typeof p[0] === "object") ? p[0] : {};
  }
  if (p && typeof p === "object") {
    if (p.json && typeof p.json === "object" && !p.trades && !p.portfolio) return p.json;
    return p;
  }
  return {};
}

const obj = unwrap(parsed);

// Look for trades under several possible keys the LLM might use
const tradeKeys = ["trades", "orders", "actions", "buyOrders", "buys"];
let rawTrades = [];
for (const k of tradeKeys) {
  if (Array.isArray(obj[k])) { rawTrades = obj[k]; break; }
}
// portfolio: only treat as trades if items have ticker/symbol AND amount/totalCost
if (rawTrades.length === 0 && Array.isArray(obj.portfolio)) {
  const looksLikeTrades = obj.portfolio.every(p => p && typeof p === "object" && (p.ticker || p.symbol) && (p.amount != null || p.totalCost != null || p.value != null));
  if (looksLikeTrades) rawTrades = obj.portfolio;
}

const trades = rawTrades
  .filter(t => t && typeof t === "object")
  .map(t => {
    const ticker = String(t.ticker || t.symbol || "").trim();
    const amt = parseFloat(t.amount != null ? t.amount : (t.totalCost != null ? t.totalCost : (t.value != null ? t.value : 0)));
    return {
      ticker: ticker,
      amount: isFinite(amt) ? amt : 0,
      reason: String(t.reason || t.rationale || "AI trade decision"),
      isDip: Boolean(t.isDip)
    };
  })
  .filter(t => {
    if (!t.ticker) return false;
    if (!(t.amount > 0)) return false;
    if (t.amount > cash) return false;
    return t.ticker.endsWith("_US_EQ") || t.ticker.endsWith("l_EQ") || t.ticker.endsWith("_EQ");
  });

return {
  json: {
    trades: trades,
    summary: String(obj.summary || obj.note || ""),
    cash: Number(obj.cash) || cash,
    tradeCount: trades.length,
    hasDipTrades: trades.some(t => t.isDip),
    parseError: null
  }
};

