const ticker = $json.ticker || ""; 
const amount = $json.amount || 0;
const reason = $json.reason || "No reason provided";
const isDip = $json.isDip || false;

if (!ticker) {
  return [{ json: { error: "Ticker was missing from input", ticker, amount, reason } }];
}

let yahooSymbol;

// Case 1: US Stocks (e.g. AAPL_US_EQ -> AAPL)
if (ticker.includes('_US_EQ')) {
  yahooSymbol = ticker.replace('_US_EQ', '');
} 
// Case 2: UK Stocks/ETFs (e.g. VUAGl_EQ -> VUAG.L)
else {
  // Strip off the _EQ
  let base = ticker.replace('_EQ', '');

  // Trading212 often adds a lowercase 'l' (for London) or 'x' to the end of ETFs.
  // We need to strip that lowercase letter off to get the real base ticker.
  if (base.match(/[a-z]$/)) {
    base = base.slice(0, -1);
  }

  // Append .L for London Stock Exchange
  yahooSymbol = base + '.L';
}

return [{
  json: {
    ticker,
    amount,
    reason,
    isDip,
    yahooSymbol
  }
}];

try {
    const chartData = $json.chart.result[0];
    const meta = chartData.meta;
    const price = meta.regularMarketPrice;

    const upstream = $('Map Ticker to Yahoo').item.json;
    const ticker = upstream.ticker;
    const amount = Number(upstream.amount) || 0;

    if (!ticker) throw new Error('Missing ticker from Map Ticker to Yahoo');
    if (!price || price <= 0) throw new Error('Invalid price from Yahoo response');
    if (amount <= 0) throw new Error('Amount must be greater than 0');

    const rawQty = amount / price;
    const quantity = Math.round(rawQty * 10000) / 10000;

    return {
          ticker,
          quantity,
          price,
          amount,
          currency: meta.currency,
          exchange: meta.exchangeName,
          yahooSymbol: meta.symbol,
          isDip: upstream.isDip,
          reason: upstream.reason,
          serverTime: new Date().toISOString()
    };
} catch (error) {
    return {
          error: 'Failed to calculate quantity: ' + error.message,
          rawError: String(error)
    };
}

