const cashData = $('GET Cash Balance').item.json;
const portfolioData = $('GET Portfolio').all ? $('GET Portfolio').all().map(i=>i.json) : [];

let tradeLog = '';
try { tradeLog = $('Read ISA Trade Log').item.json.stdout || ''; } catch(e) {}

const lines = tradeLog.split('\n').filter(l => l.includes(','));
const trades = lines.map(l => {
  const p = l.split(',');
  return {date: p[0], ticker: p[1], action: p[2], pnl: parseFloat(p[4])||0};
}).filter(t => t.action === 'BUY');

const today = new Date().toISOString().split('T')[0];
const todayTrades = trades.filter(t => t.date && t.date.startsWith(today));

let circuitBreakerTriggered = false;
let pauseReason = '';

// Daily trade limit — max 4 buys per day for ISA
if(todayTrades.length >= 4) {
  circuitBreakerTriggered = true;
  pauseReason = 'DAILY LIMIT: ' + todayTrades.length + ' trades placed today';
}

// Cash too low
const cash = cashData.free || 0;
if(cash < 5) {
  circuitBreakerTriggered = true;
  pauseReason = 'INSUFFICIENT CASH: £' + cash.toFixed(2) + ' available';
}

return [{json: {
  cash,
  portfolio: portfolioData,
  circuitBreakerTriggered,
  pauseReason,
  todayTradeCount: todayTrades.length
}}];

